/-- Covariate cube. For [the stated inputs and conditions](hyp:d), [the `cube` object being defined](goal). -/
def cube (d : ℕ) : Set (Fin d → ℝ) :=
  Set.univ.pi (fun _ => Set.Icc (0 : ℝ) 1) -- @realizes mathcalX(Borel cube [0,1]^d)

